SELECT "Hatred_1"."State_" AS "State_",   SUM(1) AS "TEMP_Calculation__454863522737569789__2109769841__0_",   CAST(MAX("Hatred_1"."StatePopNum") AS BIGINT) AS "TEMP_Per100000__copy___3451088709__0_",   CAST(MIN("Hatred_1"."StatePopNum") AS BIGINT) AS "TEMP_Per100000__copy___3855970114__0_" FROM "Hatred_1" WHERE (((("Hatred_1"."State_" >= 'AK') AND ("Hatred_1"."State_" <= 'CT')) OR (("Hatred_1"."State_" >= 'DE') AND ("Hatred_1"."State_" <= 'WY'))) AND ("Hatred_1"."Keyword" IN ('fatass', 'fatso', 'fattie'))) GROUP BY "Hatred_1"."State_" HAVING ((SUM(1) >= 30) AND (SUM(1) <= 100000));
